/* A palette refinement: saturated cabinet surround, readable opaque controls.
   Presentation only. Small/zoomed windows keep scroll access rather than clipping. */
body.pf-game{--arcade-deep:#103f50;--arcade-panel:#155469;--arcade-line:#429aa5;--arcade-paper:#fff3d1;--arcade-yellow:#ffd35b;--arcade-coral:#ff8b69;background:var(--arcade-deep)}
body.pf-game .vignette,body.pf-game.desktop-layout:not(.playing) .vignette{background:radial-gradient(ellipse at 78% 34%,#35b9bc12,transparent 58%),linear-gradient(90deg,#092d4440,transparent 55%)}
body.pf-game .pf-header{background:#103f50;border-bottom:1px solid #4a97a4;color:var(--arcade-paper)}
body.pf-game .pf-header nav button,body.pf-game .pf-header .pf-home{background:#1a6173;color:#fff5db;border:1px solid #6cb6be;border-radius:10px;font-weight:800;box-shadow:0 3px 0 #072e3b;text-decoration:none}
body.pf-game .pf-header .pf-home{background:#ffcf59;color:#123a4b;border-color:#ffdf8a}
body.pf-game .pf-header nav #sound[aria-pressed="true"]{background:#68dfc3;color:#103e4d;border-color:#adf7dd}
body.pf-game .pf-header button:disabled{opacity:.5;box-shadow:none}
body.pf-game #intro.menu-sheet{background:linear-gradient(145deg,#19576b,#103e50);color:var(--arcade-paper);border:2px solid #58acb7;border-top:5px solid #ffc956;border-radius:22px;box-shadow:0 12px 35px #05273766;justify-content:flex-start;scrollbar-color:#5cb9bd #103e50}
body.pf-game #intro h1,body.pf-game #intro h1 span,body.pf-game #intro legend{color:#fff3d1}
body.pf-game #intro .eyebrow{color:#ffcb67;letter-spacing:1px}
body.pf-game #intro h1 span:after{background:#ff8b69}
body.pf-game #intro .lede,body.pf-game #intro .menu-hint,body.pf-game #intro .home-best{color:#c5e7e5}
body.pf-game #intro .menu-choices button,body.pf-game #intro .text-button{background:#21667a;color:#fff5db;border:1px solid #71b9bf;border-radius:10px;box-shadow:0 3px 0 #072e3b}
body.pf-game #intro .menu-choices button[aria-pressed=true]{background:#ffd35b;color:#123d4e;border-color:#ffe6a0;box-shadow:0 3px 0 #9b6b2a}
body.pf-game #intro .primary{background:#ff8b69;color:#153c48;border:1px solid #ffbc96;border-radius:12px;box-shadow:0 5px 0 #913f3c;font-weight:900}
body.pf-game #intro .primary:hover{background:#ffab86}
body.pf-game #intro .intro-options{grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
body.pf-game #intro .intro-options .text-button{font-size:14px;padding:7px 4px;line-height:1.25}
body.pf-game #intro #introStorageNotice{color:#ffd0a6}
body.pf-game.playing .scorecard,body.pf-game.playing #lampHud{background:#155469;color:#fff3d1;border:1px solid #519fac;border-radius:12px;box-shadow:0 4px 12px #062b3c33}
body.pf-game.playing .scorecard{border-left:4px solid #ffcd58}
body.pf-game.playing .scorecard strong{color:#ffdc76}
body.pf-game.playing .scorecard small,body.pf-game.playing .scorecard>div{color:#c9f0e8}
body.pf-game.playing #overtimeStatus{background:#0c3d50;color:#fff4d3;border-radius:8px}
body.pf-game.playing #stationHint{white-space:normal;height:auto;max-width:228px;line-height:1.4;color:#d0eee8;font-size:12px}
body.pf-game.playing #controls .flipper{min-width:0;background:linear-gradient(155deg,#ffde75,#ffc455);border:2px solid #ffe8a1;border-bottom:5px solid #b37728;border-radius:16px;color:#173c4c;text-shadow:none;box-shadow:0 5px 15px #05293d66}
body.pf-game.playing #controls .flipper:last-child{background:linear-gradient(155deg,#ffa785,#ff855f);border-color:#ffc3a3;border-bottom-color:#a34c35}
body.pf-game.playing #controls .keycap{color:#173c4c;background:#ffffff33;border:1px solid #173c4c55;border-radius:8px;text-shadow:none}
body.pf-game.playing #controls .flipper.active,body.pf-game.playing #controls .flipper.holding{background:#fff0ad;border-bottom-width:2px;box-shadow:0 0 0 3px #ffda7299;transform:translateY(3px)}
body.pf-game.playing #controls .flipper.expected{box-shadow:0 0 0 3px #73ffe1,0 5px 18px #062d3b77}
body.pf-game.playing #mobileCue:not([hidden]){background:#155469;border:1px solid #65bfc5;color:#fff4d5;border-radius:10px;box-shadow:0 3px 10px #062d3b44}
@media(orientation:landscape){
 body.pf-game.playing .pf-header{background:#103f50;border:1px solid #418695;border-radius:0 0 14px 0;gap:6px;padding:8px}
 body.pf-game.playing #playStatus{gap:8px}
 body.pf-game.playing #lampHud{padding:8px}
}
@media(orientation:landscape) and (min-height:601px){
 body.pf-game #intro.menu-sheet{left:3%;width:40%;max-width:560px;top:calc(var(--pf-header-height) + 16px);bottom:16px;max-height:none;padding:clamp(18px,2.2vh,28px);gap:clamp(10px,1.7vh,16px);justify-content:center}
 body.pf-game #intro h1{font-size:clamp(34px,5.4vh,56px);line-height:1.02;margin:6px 0 10px}
 body.pf-game #intro .home-settings{gap:12px}
 body.pf-game #intro .lede{font-size:17px;line-height:1.3}
 body.pf-game #intro legend{font-size:17px;margin-bottom:6px}
 body.pf-game #intro .menu-choices button{font-size:16px;min-height:44px;padding:8px 5px}
 body.pf-game #intro .menu-hint{font-size:14px;line-height:1.35}
 body.pf-game #intro .primary{font-size:21px;min-height:50px;padding:10px 14px}
 body.pf-game #intro .home-start{gap:8px}
 body.pf-game #intro .home-best{font-size:14px}
}
@media(orientation:landscape) and (min-height:601px) and (max-height:720px){
 body.pf-game #intro.menu-sheet{gap:10px;padding:16px 20px;justify-content:flex-start}
 body.pf-game #intro h1 br{display:none}
 body.pf-game #intro h1{font-size:34px}
 body.pf-game #intro .eyebrow{font-size:12px}
}
@media(orientation:landscape) and (max-height:600px){
 body.pf-game.playing .pf-header{gap:2px;padding:4px}
 body.pf-game.playing #playStatus{gap:3px}
 body.pf-game.playing #lampHud{padding:3px}
 body.pf-game.playing #controls .flipper{width:136px;min-height:54px;border-radius:12px}
}
@media(orientation:portrait){
 body.pf-game.playing #lampHud{background:none;border:0;box-shadow:none;border-radius:0}
 body.pf-game.playing .scorecard{border-radius:8px}
 body.pf-game.playing #controls .flipper{width:30%;max-width:122px;min-height:56px;border-radius:14px}
 body.pf-game #intro.menu-sheet{border-radius:18px}
}
/* Browser zoom commonly makes a desktop's effective height 550–600px.
   Do not let the older desktop h1 specificity inflate this compact menu. */
@media(orientation:landscape) and (min-height:521px) and (max-height:720px){
 body.pf-game #intro.menu-sheet{left:3%;width:42%;max-width:560px;top:calc(var(--pf-header-height) + 10px);bottom:10px;max-height:none;padding:14px 18px;gap:8px;justify-content:flex-start}
 body.pf-game #intro h1{font-size:32px;line-height:1.05;margin:4px 0 6px}
 body.pf-game #intro h1 br{display:none}
 body.pf-game #intro .eyebrow{font-size:12px;line-height:1.2}
 body.pf-game #intro .lede{font-size:15px;line-height:1.3}
 body.pf-game #intro .home-settings{gap:8px}
 body.pf-game #intro legend{font-size:16px;line-height:1.2;margin-bottom:4px}
 body.pf-game #intro .menu-choices button{font-size:15px;min-height:44px;padding:6px 4px}
 body.pf-game #intro .menu-hint{font-size:13px;line-height:1.3}
 body.pf-game #intro .primary{min-height:46px;font-size:19px;padding:8px 12px}
 body.pf-game #intro .home-start{gap:6px}
 body.pf-game #intro .home-best{font-size:13px;line-height:1.2}
 body.pf-game #intro .intro-options .text-button{font-size:13px;min-height:44px;padding:6px 3px}
}

/* Keyboard hints: screen L/R labels are controls, not literal keyboard keys.
   Coarse-pointer phones keep the existing clean L/R touch presentation. */
body.pf-game.playing #controls kbd{display:none}
body.pf-game.desktop-layout.playing #controls .control-label{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;line-height:1.15}
body.pf-game.desktop-layout.playing #controls kbd{display:block;font:800 14px/1.2 system-ui,sans-serif;letter-spacing:1px;white-space:nowrap;color:#153c48;background:#fff4d580;border:1px solid #153c4833;border-radius:6px;padding:3px 7px}
body.pf-game.desktop-layout.playing #controls .flipper{gap:10px}
body.pf-game.desktop-layout.playing #interactionOffer b,body.pf-game.desktop-layout.playing #routeChoice span,body.pf-game.desktop-layout.playing #routeChoice small{white-space:normal;overflow-wrap:normal;line-height:1.35}
body.pf-game.desktop-layout.playing #activityText{overflow-wrap:normal;line-height:1.35}
@media(hover:none),(pointer:coarse){body.pf-game.desktop-layout.playing #controls kbd{display:none}}

/* In-frame menus rotate together with the canvas, including dynamic dialogs. */
body.pf-game .game-menu-backdrop{position:fixed;inset:0;background:#061f32c9;touch-action:none}
body.pf-game dialog[data-game-menu]{position:fixed;inset:0;margin:auto;transform:none;width:min(640px,calc(100vw - 24px));max-width:calc(100vw - 24px);max-height:calc(100dvh - 24px);height:fit-content;padding:20px;border:2px solid #63b4bf;border-top:5px solid #ffd35b;border-radius:18px;background:#fff3d5;color:#153c48;overflow:auto;overscroll-behavior:contain;touch-action:pan-y;box-shadow:0 12px 40px #031c3066}
body.pf-game dialog[data-game-menu]:not([open]){display:none!important}
body.pf-game dialog[data-game-menu][open]{display:block}
body.pf-game dialog[data-game-menu] button{min-height:44px;border-radius:10px;line-height:1.3;white-space:normal;touch-action:manipulation}
body.pf-game dialog[data-game-menu] h2{margin:0 0 14px;font-size:25px;line-height:1.2;color:#153c48}
body.pf-game dialog[data-game-menu] p{font-size:15px;line-height:1.5;color:#294c50}
body.pf-game dialog[data-game-menu] select[hidden]{display:none!important}
body.pf-game .game-menu-choices{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0 16px}
body.pf-game .game-menu-choices button{flex:1 1 120px;font-size:16px;font-weight:800;padding:10px 12px;background:#21667a;color:#fff5db;border:1px solid #71b9bf}
body.pf-game .game-menu-choices button[aria-pressed="true"]{background:#ffd35b;color:#123d4e;border:2px solid #986728}
body.pf-game .game-menu-choices button[aria-pressed="true"]:after{content:' ✓'}
body.pf-game dialog[data-game-menu] :focus-visible{outline:3px solid #ba512d;outline-offset:3px}
@media(orientation:landscape) and (max-height:520px){body.pf-game dialog[data-game-menu]{width:min(740px,calc(100vw - 20px));max-height:calc(100dvh - 16px);padding:14px 18px;border-radius:14px}body.pf-game dialog[data-game-menu] h2{font-size:22px;margin-bottom:10px}body.pf-game .game-menu-choices{margin-bottom:10px}}
body.pf-game #pauseScreen[data-game-menu]:not([open]){display:none!important}
body.pf-game #pauseScreen[data-game-menu][open]{display:grid}

/* Entry preview uses the live board; navigation stays inside the game first. */
body.pf-game .pf-header .pf-home{cursor:pointer;white-space:nowrap;font-size:14px}
body.pf-game #homeConfirm{box-sizing:border-box;width:min(440px,calc(100% - 28px));max-height:calc(100dvh - 28px);overflow:auto;background:#155469;color:#fff3d1;border:2px solid #71b9bf;border-top:5px solid #ffd35b;border-radius:18px;padding:22px;box-shadow:0 12px 35px #05273788}
body.pf-game #homeConfirm h2{font-size:24px;line-height:1.3;margin:0 0 12px;color:#fff3d1}
body.pf-game #homeConfirm p{font-size:16px;line-height:1.5;margin:0 0 18px}
body.pf-game .home-confirm-actions{display:grid;grid-template-columns:1fr 1fr;gap:10px}
body.pf-game #homeConfirm button{min-height:48px;padding:10px;font-size:16px;line-height:1.3;border-radius:10px;font-weight:800;white-space:normal}
body.pf-game #homeCancel{background:#ffd35b;color:#123d4e;border:1px solid #ffe6a0}
body.pf-game #homeAccept{background:#21667a;color:#fff5db;border:1px solid #71b9bf}
@media(max-width:600px){body.pf-game .pf-header .pf-home{font-size:12px;padding:0 6px}}

/* Menu scrolling stays browser-native inside the optionally 90-degree iframe.
   Do not constrain gesture recognition to one screen axis or cancel touchmove.
   Gameplay canvas/L/R retain their separate touch-action:none rules. */
body.pf-game #intro.menu-sheet,
body.pf-game #pauseScreen,
body.pf-game #pauseScreen .pause-menu,
body.pf-game dialog[data-game-menu]{touch-action:manipulation;overscroll-behavior:contain;-webkit-overflow-scrolling:touch}
/* Centered overflowing grid content can begin above scrollTop=0 on short screens. */
body.pf-game #intro.menu-sheet{align-content:start}

/* Desktop window and browser F11 share one resize-driven layout. F11 is not
   document.fullscreenElement; never gate this geometry on the Fullscreen API. */
body.pf-game.desktop-layout.playing #controls{left:calc(var(--safe-left,0px) + 12px);right:calc(var(--safe-right,0px) + 12px);bottom:calc(var(--safe-bottom,0px) + 12px);height:80px;align-items:stretch;justify-content:space-between}
body.pf-game.desktop-layout.playing #controls .flipper{min-height:64px;height:80px;max-width:calc(50vw - 24px)}
body.pf-game.desktop-layout.playing #controls kbd{display:inline-block}
body.pf-game.desktop-layout #homeConfirm p{color:#fff5db;opacity:1;font-size:17px;line-height:1.5}
body.pf-game.desktop-layout #homeCancel{display:flex;align-items:center;justify-content:center;text-align:center;font-size:23px;font-weight:900;line-height:1.25;min-height:56px;padding:12px 18px}

body.pf-game #restartConfirm{background:#155469;color:#fff5db;width:min(440px,calc(100vw - 28px))}
body.pf-game #restartConfirm h2,body.pf-game #restartConfirm p{color:#fff5db}
body.pf-game #restartConfirm .restart-actions{display:flex;flex-wrap:wrap;gap:12px}
body.pf-game #restartConfirm button{flex:1 1 140px;min-height:48px;font-size:18px;font-weight:800;text-align:center;padding:10px;background:#ffd35b;color:#123d4e;border:2px solid #986728}
body.pf-game #world:focus{outline:none}

import {createTabletCueProjection} from './tablet-cue-projection.js';
import {mountRestartConfirmation,focusGameplay} from './restart-confirmation.js';
import {mountHomeNavigation} from './home-navigation.js';
import {installGameMenus,syncMenuChoices} from './game-menus.js';
import {keyboardHint} from './keyboard-hints.js';
import {OFFICE_PALETTE as C,OFFICE_SURFACES,paintOfficeFloor} from './office-palette.js';
import {buildOfficePartitions} from './office-partitions.js';
import {mountMobileUI} from './mobile-ui.js';
import {createRouteVisuals} from './route-visual.js';
import {mountRouteHud} from './route-hud.js';
import {createLotteryStatus} from './lottery-hud.js';
import {LOTTERY_BOX} from './lottery-layout.js';
import {LOTTERY_PRIZES} from './lottery-events.js';
import {createLotteryVisuals} from './lottery-visual.js';
import {createLotteryCoworkers} from './lottery-coworkers.js';
import {lotteryPlacements} from './lottery-placement.js';
import {createOfferStationVisual} from './offer-station-visual.js';
import {mountInteractionOffer} from './overtime-ui.js';
import {overtimePresentation,overtimeCueText,PAY_NAMES} from './overtime-presentation.js';
import {createShadowWorkerVisuals} from './shadow-worker-visual.js';
import {mountReleaseRecovery} from './release-recovery.mjs';
import{recordPlayStart}from'../shared/play-counts.mjs';
import {clipIntroFrame} from './platform-layout.mjs';
import {mountPinballPlatform} from './platform-ui.mjs';
import {placeFeedback} from './feedback-layout.js';
import {openingPose,advanceOpening,openingFinished,poseOpeningBoss,openingContact,openingFlight} from './opening.js';
import {createStationLabels} from './station-labels.js';
import {clockCue} from './clock-cue.js';
import {bossPath} from './round-rules.js';
import {RoundOptions} from './round-options.js';
import {bossVisualState} from './boss-visual.js';
import {installViewportRecovery} from './viewport-recovery.js';
import {buildComboOffice} from './combo-office.js';
import {COMBO_ROUTES} from './combo-routes.js';
import {buildAssists} from './assist-office.js';
import {JetWake} from './jet-wake.js';
import {GameAudio} from './game-audio.js';
import {buildOfficeStory} from './office-stories.js';
import {DOOR,buildDoor,buildCompanySign} from './company-design.js';
import {specialFeedback} from './special-feedback.js';
import {buildSpecialStation} from './special-office.js';
import {canvasSize,fitLabelFont,renderRatio} from './text-layout.js';
import {buildMailOffice} from './mail-office.js';
import {mailPhase} from './mail-run.js';
import {buildDispatchCourt} from './dispatch-court.js';
import {setupPlayLayout,playFrame,blendPlayFrame,playSafeInsets} from './play-layout.js';
import {setupIntro,introFrame as originalIntroFrame,fittedIntro} from './intro.js';
const introFrame=()=>clipIntroFrame(originalIntroFrame(),innerHeight,document.querySelector('.pf-header')?.getBoundingClientRect().height||0);
import {WINDOWS,LAMPS} from './board-features.js';
import {buildOfficeFeatures,stableWindow} from './office-features.js';
import {predictLanding} from './prediction.js';
import * as T from './vendor/three.module.min.js';
import {Game,STEP,BUMPERS,FIELD,FLIPPER,flipperSegment,clamp} from './physics.js';
import {StableRig,overviewPose,controlSide,SLOPE} from './camera.js';
import {createCharacter,poseCharacter} from './character.js';
import {chairRenderPose,busyRenderHeight,busyRenderForward,launcherRenderHeight,updateWaterJet,coffeeRenderHeight,keepLauncherFeetAboveSurface,keepCoffeeFeetAboveFloor} from './render-proportions.js';
import {ACTIVITIES,activityFor,stageYaw} from './activities.js';
import {successfulInteraction} from './interactions.js';
import {ActorVisibility} from './occlusion.js';
installGameMenus(document);
if(parent!==window)document.body.classList.add('embedded-game');
const view=new URLSearchParams(location.search).get('view')==='original'?'original':'reverse';
const cameraRig=new StableRig(view);
const cameraPose=(w,h,mode,b)=>{if(mode==='intro'){const frame=introFrame();return frame?fittedIntro(frame.w,frame.h,view):overviewPose(w,h,view);}const f=playFrame(),r=new StableRig(view);r.reset(b);return r.update(0,f.w,f.h,b,null,null,comfort,{portrait:w<h,...playSafeInsets()});};
const physicalSide=side=>controlSide(side,view),physicalInput=()=>view==='reverse'?{left:input.right,right:input.left}:input;
let roundStorage;try{roundStorage=localStorage;}catch{}
const roundOptions=new RoundOptions(roundStorage);
const $=id=>document.getElementById(id),game=new Game({view,random:Math.random,roundLimit:roundOptions.limit}),input={left:false,right:false};
let interactionOfferUI,routeVisuals,routeHud;
let overtimeVisuals,lastShadowSound=-Infinity,shadowAwardPending=0,shadowAwardAt=0;
let homeNavigation,mobileUI,lotteryVisuals,lotteryCoworkers,offerStationVisual,stationLabels,renderer,scene,camera,office,person,shadow,flipperMeshes={},bumperGroups={},particles=[],clock=0,accumulator=0,mode='intro',introTime=0,best=0,transition=0,interactionsOn=true,cinematicTime=0,cinematicStart=null,followAnchor=new T.Vector3(),pausedMode='playing',comicUntil=0;
const stats={frames:0,maxDrawCalls:0,lastEffect:null,visibility:null};
const gameAudio=new GameAudio();let jetWake,platform;
let comboOffice,assistOffice,mailOffice,economy=false,features,visibility,activityProps={},landingMarker,landingLine,lastPrediction=-1;
const stableWindows=true;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let comfort=reduced;
best=roundOptions.best();
const money=n=>'$'+Math.floor(n).toLocaleString('en-US');$('bestIntro').textContent='個人最高 '+money(best);

const materials=new Map();
function mat(color){if(!materials.has(color))materials.set(color,new T.MeshToonMaterial({color}));return materials.get(color);}
function shape(geo,color,parent=office,x=0,y=0,z=0){const m=new T.Mesh(geo,mat(color));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;m.userData.occludes=true;parent.add(m);const outline=new T.LineSegments(new T.EdgesGeometry(geo,28),new T.LineBasicMaterial({color:C.ink}));m.add(outline);return m;}
function box(w,h,d,color,parent,x=0,y=0,z=0){return shape(new T.BoxGeometry(w,h,d),color,parent,x,y,z);}
function cylinder(r,h,color,parent,x=0,y=0,z=0,segments=12){return shape(new T.CylinderGeometry(r,r,h,segments),color,parent,x,y,z);}
function sphere(r,color,parent,x=0,y=0,z=0){return shape(new T.SphereGeometry(r,12,8),color,parent,x,y,z);}
function label(text,w,h,color='#193a3c',bg='#f0e9c9'){
 const canvas=document.createElement('canvas'),size=canvasSize(w,h);canvas.width=size.width;canvas.height=size.height;const ctx=canvas.getContext('2d');ctx.fillStyle=bg;ctx.fillRect(0,0,size.width,size.height);ctx.strokeStyle=color;ctx.lineWidth=Math.max(2,size.height*.035);const inset=ctx.lineWidth;ctx.strokeRect(inset,inset,size.width-inset*2,size.height-inset*2);ctx.fillStyle=color;const font=fitLabelFont(text,size,n=>{ctx.font=`900 ${n}px "Noto Sans TC","Microsoft JhengHei",sans-serif`;return ctx.measureText(text).width;});ctx.font=`900 ${font}px "Noto Sans TC","Microsoft JhengHei",sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(text,size.width/2,size.height*.53);const tex=new T.CanvasTexture(canvas);tex.colorSpace=T.SRGBColorSpace;tex.anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());
 const m=new T.Mesh(new T.PlaneGeometry(w,h),new T.MeshBasicMaterial({map:tex,side:T.FrontSide}));m.userData.occludes=true;m.userData.text=text;m.userData.labelType='world';m.userData.textMetrics={...size,font};return m;
}
function floorLabel(text,x,z,w=3,h=.7,bg){const m=label(text,w,h,'#234344',bg);m.rotation.x=-Math.PI/2;m.rotation.z=view==='reverse'?0:Math.PI;m.userData.labelType='floor'; m.position.set(-x,.065,z);m.userData.occludes=false;office.add(m);return m;}
const character=createCharacter;
function buildOffice(){
 office=new T.Group();office.rotation.x=SLOPE;scene.add(office);
