for(const view of ['original','reverse'])for(const id of ['chair','desk','launcher'])test(`actual Game docking/launch preserves readable surface clearance ${id}/${view}`,async()=>{const f=await fixture(root,view),station=f.BUMPERS.find(o=>o.id===id),g=new Game({view,patrol:false});g.start();const dock=f.dockFor(station,view);Object.assign(g.ball,{x:dock.x+3,z:dock.z-3});assert.ok(g.startInteraction(station,'left',false));const person=f.createCharacter(),stageCounts={docking:0,work:0,launch:0};let launchChecks=0;for(let n=0;n<1200&&g.interaction;n++){g.updateInteraction(1/120,{});const i=g.interaction;if(!i)break;stageCounts[i.stage]++;const a=i.activity,cp=a==='chair'?helpers.chairRenderPose(station.visualScale,i.stage,i.elapsed,i.dockDuration,i.launchElapsed):null,rootY=cp?cp.y:a==='busy'?helpers.busyRenderHeight(station.visualScale,i.stage,i.elapsed,i.dockDuration,i.launchElapsed):helpers.launcherRenderHeight(i.elapsed,i.stage,i.dockDuration,i.launchElapsed),yaw=(a==='chair'?i.spinAngle:Math.PI)+f.stageYaw(view);person.position.set(-(g.ball.x-station.x)-(cp?Math.sin(yaw)*cp.forward:0),rootY+g.hop,g.ball.z-station.z-(cp?Math.cos(yaw)*cp.forward:0));person.rotation.y=yaw;if(a==='busy'){const forward=helpers.busyRenderForward(i.stage,i.elapsed,i.dockDuration,i.launchElapsed);person.position.x-=Math.sin(yaw)*forward;person.position.z-=Math.cos(yaw)*forward;}f.poseCharacter(person,{activity:['docking','launch'].includes(i.stage)?'flight':a,time:i.elapsed,progress:0});person.updateMatrixWorld(true);const ballBefore=JSON.stringify(g.ball);if(id==='launcher')helpers.keepLauncherFeetAboveSurface(person,f.assistOffice.models.center.root,Math.min(1,i.elapsed/.35)*1.2);assert.equal(JSON.stringify(g.ball),ballBefore);person.updateMatrixWorld(true);assert.ok(person.position.toArray().every(Number.isFinite));if(id==='launcher'){const inv=f.assistOffice.models.center.root.matrixWorld.clone().invert(),lift=Math.min(1,i.elapsed/.35)*1.2;for(const side of ['left','right']){const shoe=person.getObjectByName(side+'Shoe');shoe.geometry.computeBoundingBox();const b=shoe.geometry.boundingBox;for(const x of[b.min.x*1.035,b.max.x*1.035])for(const y of[b.min.y*1.035,b.max.y*1.035])for(const z of[b.min.z*1.035,b.max.z*1.035]){const v=new f.T.Vector3(x,y,z).applyMatrix4(shoe.matrixWorld).applyMatrix4(inv),paper=Math.abs(v.x)<=.45&&Math.abs(v.z)<=.325,disc=Math.hypot(v.x,v.z)<=2.3;if(paper||disc)assert.ok(v.y>=(paper?.49:.22)+lift-.001,`${i.stage} surface crossing ${v.toArray()}`);}}}if(i.stage==='launch'){launchChecks++;assert.ok(i.launchRoute&&i.release,'actual solver creates launch route');if(id==='launcher'){const inv=f.assistOffice.models.center.root.matrixWorld.clone().invert();for(const side of ['left','right']){const shoe=person.getObjectByName(side+'Shoe');shoe.geometry.computeBoundingBox();const b=shoe.geometry.boundingBox.clone();b.min.multiplyScalar(1.035);b.max.multiplyScalar(1.035);for(const x of[b.min.x,b.max.x])for(const y of[b.min.y,b.max.y])for(const z of[b.min.z,b.max.z]){const p=new f.T.Vector3(x,y,z).applyMatrix4(shoe.matrixWorld).applyMatrix4(inv);if(Math.abs(p.x)<=.45&&Math.abs(p.z)<=.325)assert.ok(p.y>=1.69-.001,`launch foot crosses paper ${p.toArray()} t${i.launchElapsed}`);}}}}}assert.ok(stageCounts.docking>0&&stageCounts.work>0&&launchChecks>20,JSON.stringify(stageCounts));});
test('launcher render clearance distinguishes small paper stack, lower disc and outside area',async()=>{const f=await fixture(root),platform=f.assistOffice.models.center.root;for(const [x,expected]of[[0,1.69],[1.4,1.42],[5,null]]){const p=f.createCharacter();p.position.set(x,1.34,0);f.poseCharacter(p,{activity:'flight',time:.5});const before=p.position.y,delta=helpers.keepLauncherFeetAboveSurface(p,platform,1.2),bottom=f.bounds(p).min.y;if(expected===null){assert.equal(delta,0);assert.equal(p.position.y,before);}else{assert.ok(delta>0);assert.ok(Math.abs(bottom-expected)<.001,`${x}: ${bottom}`);}}const main=readFileSync(root+'/public/games/overtime-pinball/main.js','utf8');assert.match(main,/if\(a==='launcher'\)keepLauncherFeetAboveSurface\(person,assistOffice\.models\.center\.root,Math\.min\(1,i\.elapsed\/\.35\)\*1\.2\)/);});
for(const view of['original','reverse'])test(`busy shins clear stool and fingertips stay at keyboard surface ${view}`,async()=>{assert.equal(typeof helpers.busyRenderForward,'function');const f=await fixture(root,view),o=f.BUMPERS.find(o=>o.id==='desk'),dock=f.dockFor(o,view),keyboard=f.bumperGroups.desk.getObjectByName('keyboard'),stool=f.activityProps.stool;f.activityProps.root.visible=true;f.activityProps.root.scale.setScalar(o.visualScale);f.activityProps.root.rotation.y=f.stageYaw(view);f.office.updateMatrixWorld(true);const top=f.bounds(keyboard).max.y;for(let n=0;n<120;n++){const p=f.createCharacter(),yaw=Math.PI+f.stageYaw(view),forward=helpers.busyRenderForward('work');p.position.set(-(dock.x-o.x)-Math.sin(yaw)*forward,helpers.busyRenderHeight(o.visualScale,'work'),dock.z-o.z-Math.cos(yaw)*forward);p.rotation.y=yaw;f.poseCharacter(p,{activity:'busy',time:n/20,progress:n/120});p.updateMatrixWorld(true);for(const side of['left','right']){const knee=p.userData.rig[side].knee.getWorldPosition(new f.T.Vector3());f.activityProps.root.worldToLocal(knee);assert.ok(knee.z> -1.85+1.1/2,'knee stays beyond stool front');const hand=p.userData.rig[side].hand,fingers=hand.children.filter(m=>m.geometry?.type==='CapsuleGeometry');assert.equal(fingers.length,3);for(const finger of fingers){const b=f.bounds(finger),minY=b.min.y,center=b.getCenter(new f.T.Vector3());keyboard.worldToLocal(center);assert.ok(Math.abs(center.x)<.35&&Math.abs(center.z)<.18,'finger must be over key footprint, not merely at same height');assert.ok(minY>=top-.01&&minY<=top+.05,`finger ${minY} vs keyboard ${top}`);}}}});
test('lowered chair shaft meets cushion underside without protruding through its top',async()=>{const f=await fixture(root),model=f.bumperGroups.chair.getObjectByName('mechanism'),seat=model.getObjectByName('chairSeat'),shaft=model.getObjectByName('chairShaft');assert.ok(shaft);const s=f.bounds(seat),pole=f.bounds(shaft);assert.ok(pole.max.y<=s.max.y&&pole.max.y>=s.min.y);});
test('fixed shredder salary label sits below intake and does not cover the slot',async()=>{const f=await fixture(root),m=f.bumperGroups.shredder,label=m.getObjectByName('shredderSalaryLabel'),intake=m.getObjectByName('shredderIntake');assert.ok(label);assert.ok(f.bounds(label).max.y<f.bounds(intake).min.y);});
test('busy fingertips remain above live animated keyboard cap through pull pulses',async()=>{const f=await fixture(root),keyboard=f.bumperGroups.desk.getObjectByName('keyboard'),source=readFileSync(root+'/public/games/overtime-pinball/main.js','utf8'),expression=source.match(/if\(keyboard\)keyboard\.scale\.y=([^;]+);/)[1],scale=new Function('i','a','return '+expression),p=f.createCharacter();p.position.y=helpers.busyRenderHeight(1.1,'work');for(let pulls=0;pulls<6;pulls++)for(let n=0;n<=30;n++){const pulse=n/100;keyboard.scale.y=scale({pullPulse:pulse},'busy');const top=f.bounds(keyboard).max.y;f.poseCharacter(p,{activity:'busy',time:pulls*.65+pulse*2,progress:pulls/6});for(const side of['left','right'])for(const finger of p.userData.rig[side].hand.children.filter(m=>m.geometry?.type==='CapsuleGeometry'))assert.ok(f.bounds(finger).min.y>=top-.01,`animated key ${top} pierces finger ${f.bounds(finger).min.y}`);}});
